// ❌ OLD: Manually juggling optimistic state, error backups, loading flags,
// and race conditions when multiple submissions occur in parallel.
import { useState } from 'react';

export default function TodoList({ initialTodos, addTodoAction }) {
  const [todos, setTodos] = useState(initialTodos);
  const [loading, setLoading] = useState(false);

  async function handleAdd(formData) {
    const title = formData.get('title');
    const previous = todos;
    setTodos([...todos, { id: 'temp', title, pending: true }]);
    setLoading(true);
    try {
      const saved = await addTodoAction(title);
      setTodos([...previous, saved]);
    } catch (e) {
      setTodos(previous); // Rollback manually on error
    } finally {
      setLoading(false);
    }
  }

  return <form action={handleAdd}><input name="title" /><button disabled={loading}>Add</button></form>;
}

import { useActionState, useOptimistic } from 'react';

// ✅ NEW: React 19 handles optimistic rendering and automatic rollback on failure.
export default function TodoList({ initialTodos, updateServerAction }) {
  const [todos, formAction, isPending] = useActionState(updateServerAction, initialTodos);
  const [optimisticTodos, addOptimistic] = useOptimistic(
    todos,
    (current, newTodoTitle) => [...current, { id: 'temp', title: newTodoTitle, pending: true }]
  );

  async function handleSubmit(formData) {
    const title = formData.get('title');
    addOptimistic(title); // Instantly shows in UI
    await formAction(formData); // Automatically settles or rolls back
  }

  return (
    <div>
      <form action={handleSubmit}>
        <input name="title" required />
        <button disabled={isPending}>Add Todo</button>
      </form>
      <ul>
        {optimisticTodos.map((t) => (
          <li key={t.id} style={{ opacity: t.pending ? 0.5 : 1 }}>
            {t.title}
          </li>
        ))}
      </ul>
    </div>
  );
}
